<section class="dashboard-hero"><span class="hero-icon"><i class="bi bi-circle-square"></i></span><div><p class="section-label">PELL</p><h2>Pelletisation</h2><p>BTI déchets, additifs, formulations versionnées, OF, rendements et coûts.</p></div><a href="<?=e(base_url('transfers'))?>" class="page-action">Transférer vers DEVCO</a></section><?php if($success):?><div class="app-alert app-alert-success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="app-alert app-alert-error"><?=e($error)?></div><?php endif;?>
<section class="form-panel"><h3>Transfert de déchets vers PELL</h3><form method="post" action="<?=e(base_url('pelletization/waste-transfers'))?>" class="enterprise-form"><?=csrf_field()?><div class="form-grid"><label><span>Lot de déchets</span><select name="waste_stock_id"><?php foreach($refs['wastes'] as$w):?><option value="<?=$w['id']?>"><?=e($w['site_code'].' / '.$w['type_name'].' / '.($w['batch_number']?:'-').' / '.$w['quantity_kg'].' kg')?></option><?php endforeach;?></select></label><label><span>Quantité kg</span><input type="number" step="0.001" min="0.001" name="quantity_kg"></label></div><button class="btn-primary">Créer BTI</button></form><table class="enterprise-table"><tbody><?php foreach($transfers as$t):?><tr><td><?=e($t['transfer_number'])?></td><td><?=e(($t['batch_number']?:'-').' — '.$t['waste_type'].' — '.$t['quantity_kg'].' kg')?></td><td><?=e($t['status'])?></td><td><?php if($t['status']==='draft'):?><form method="post" action="<?=e(base_url('pelletization/waste-transfers/'.$t['id'].'/ship'))?>"><?=csrf_field()?><button>Valider/expédier</button></form><?php elseif($t['status']==='in_transit'):?><form method="post" action="<?=e(base_url('pelletization/waste-transfers/'.$t['id'].'/receive'))?>"><?=csrf_field()?><button>Réceptionner PELL</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></section>
<section class="form-panel"><h3>Achat d’additif</h3><form method="post" action="<?=e(base_url('pelletization/additives'))?>" class="enterprise-form"><?=csrf_field()?><div class="form-grid"><label><span>Additif</span><select name="additive_id"><?php foreach($refs['additives'] as$a):?><option value="<?=$a['id']?>"><?=e($a['name'].' — stock '.$a['quantity_kg'].' kg')?></option><?php endforeach;?></select></label><label><span>Quantité</span><input type="number" step="0.001" name="quantity_kg"></label><label><span>Coût unitaire</span><input type="number" step="0.0001" name="unit_cost"></label></div><button class="btn-primary">Créer achat additif</button></form><p>Les achats créés doivent être réceptionnés par un autre utilisateur via leur identifiant.</p><form method="post" action="<?=e(base_url('pelletization/additives/0/receive'))?>" onsubmit="this.action=this.action.replace('/0/','/'+this.purchase_id.value+'/')"><?=csrf_field()?><input name="purchase_id" type="number" placeholder="ID achat"><button>Réceptionner</button></form></section>
<?php if(Auth::can('pelletization','administer')):?><section class="form-panel"><h3>Nouvelle version de recette</h3><form method="post" action="<?=e(base_url('pelletization/recipes'))?>" class="enterprise-form"><?=csrf_field()?><div class="form-grid"><input name="code" placeholder="Code recette" required><input name="name" placeholder="Nom" required><select name="waste_type_id"><?php foreach($refs['waste_types'] as$x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select><input name="waste_percent" type="number" step="0.001" placeholder="% déchet"><select name="additive_id"><?php foreach($refs['additives'] as$x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select><input name="additive_percent" type="number" step="0.001" placeholder="% additif"><input name="notes" placeholder="Notes/version"></div><button class="btn-primary">Créer nouvelle version</button></form></section><?php endif;?>
<section class="form-panel"><h3>Nouvel ordre de fabrication</h3><form method="post" action="<?=e(base_url('pelletization/orders'))?>" class="enterprise-form"><?=csrf_field()?><div class="form-grid"><select name="recipe_version_id"><?php foreach($refs['recipes'] as$r):?><option value="<?=$r['id']?>"><?=e($r['code'].' v'.$r['version_number'])?></option><?php endforeach;?></select><select name="waste_stock_id"><?php foreach($refs['wastes'] as$w):if($w['site_code']!=='PELL')continue;?><option value="<?=$w['id']?>"><?=e($w['type_name'].' / '.($w['batch_number']?:'-').' / '.$w['quantity_kg'].' kg')?></option><?php endforeach;?></select><select name="additive_id"><?php foreach($refs['additives'] as$a):?><option value="<?=$a['id']?>"><?=e($a['name'])?></option><?php endforeach;?></select><input type="number" step="0.001" name="theoretical_input_kg" placeholder="Entrée théorique"></div><button class="btn-primary">Créer et démarrer OF</button></form></section>
<section class="table-panel"><h3>Ordres de fabrication</h3><table class="enterprise-table"><thead><tr><th>OF</th><th>Recette</th><th>Théorique</th><th>Réel</th><th>Production</th><th>Perte</th><th>Rendement</th><th>Coût/kg</th><th>Action</th></tr></thead><tbody><?php foreach($orders as$o):?><tr><td><?=e($o['order_number'])?></td><td><?=e($o['recipe_code'].' v'.$o['version_number'])?></td><td><?=e($o['theoretical_input_kg'])?></td><td><?=e($o['actual_input_kg'])?></td><td><?=e($o['output_quantity_kg'])?></td><td><?=e($o['loss_quantity_kg'])?></td><td><?=e($o['yield_percent'])?>%</td><td><?=e($o['cost_per_kg'])?></td><td><?php if($o['status']==='in_progress'):?><form method="post" action="<?=e(base_url('pelletization/orders/'.$o['id'].'/results'))?>"><?=csrf_field()?><input name="waste_actual_kg" type="number" step="0.001" placeholder="Déchets réels"><input name="additive_actual_kg" type="number" step="0.001" placeholder="Additifs réels"><input name="output_quantity_kg" type="number" step="0.001" placeholder="Récupéré"><button>Soumettre</button></form><?php elseif($o['status']==='results_submitted'):?><form method="post" action="<?=e(base_url('pelletization/orders/'.$o['id'].'/validate'))?>"><?=csrf_field()?><button>Valider</button></form><?php elseif($o['status']==='validated'):?><form method="post" action="<?=e(base_url('pelletization/orders/'.$o['id'].'/package'))?>"><?=csrf_field()?><select name="packaging_item_id"><?php foreach($packagingItems as$item):?><option value="<?=$item['id']?>"><?=e($item['code'].' — '.$item['unit_capacity_kg'].' kg')?></option><?php endforeach;?></select><input name="bags_count" type="number" min="1" placeholder="Sacs"><button>Conditionner</button></form><?php else:?><?=e($o['status'])?><?php endif;?></td></tr><?php endforeach;?></tbody></table></section>
